import{_ as s,a0 as a,w as l,s as m,ao as p,I as r,a1 as o,A as i,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse(`{"title":"設置iSCSI的發起程序（客户端）（三） | LCTT x X-CMD","titleTemplate":false,"description":"設置iSCSI的發起程序（客户端）（三） | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"設置iSCSI的發起程序（客户端）（三） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"設置iSCSI的發起程序（客户端）（三） | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20141217 Centralized Secure Storage (iSCSI)-- 'Initiator Client' Setup on RHEL or CentOS or Fedora -Part III","title":"設置iSCSI的發起程序（客户端）（三）","tag":"201503","desc":""},"relativePath":"201503/20141217 Centralized Secure Storage (iSCSI)-- 'Initiator Client' Setup on RHEL or CentOS or Fedora -Part III.md","filePath":"[post].md"}`),d={name:"201503/20141217 Centralized Secure Storage (iSCSI)-- 'Initiator Client' Setup on RHEL or CentOS or Fedora -Part III.md"};function g(c,t,u,w,S,f){const n=a("Link");return l(),m("div",null,[t[15]||(t[15]=p('<h1 id="設置iscsi的發起程序-客户端-三" tabindex="-1">設置iSCSI的發起程序（客户端）（三） <a class="header-anchor" href="#設置iscsi的發起程序-客户端-三" aria-label="Permalink to “設置iSCSI的發起程序（客户端）（三）”">​</a></h1><p><strong>iSCSI</strong> 發起程序是一種用於同 iSCSI 目標器認證並訪問服務器上共享的LUN的客户端。我們可以在本地掛載的硬盤上部署任何操作系統，只需要安裝一個包來與目標器驗證。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Client-Initiator-Setup.jpg" alt="Client Initiator Setup"></p><p><em>初始器客户端設置</em></p><h3 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to “功能”">​</a></h3><ul><li>可以處理本地掛載磁盤上的任意文件系統</li><li>在使用fdisk命令分區後不需要重啓系統</li></ul><h3 id="前置閲讀" tabindex="-1">前置閲讀 <a class="header-anchor" href="#前置閲讀" aria-label="Permalink to “前置閲讀”">​</a></h3>',7)),r("ul",null,[r("li",null,[o(n,{href:"http://linux.cn/article-4971-1.html"},{default:i(()=>[...t[0]||(t[0]=[e("使用iSCSI Target創建集中式安全存儲（一）",-1)])]),_:1})]),r("li",null,[o(n,{href:"http://linux.cn/article-4972-1.html"},{default:i(()=>[...t[1]||(t[1]=[e("在 iSCSI Target 服務器中使用LVM創建和設置LUN（二）",-1)])]),_:1})])]),t[16]||(t[16]=p(`<h4 id="我的客户端設置" tabindex="-1">我的客户端設置 <a class="header-anchor" href="#我的客户端設置" aria-label="Permalink to “我的客户端設置”">​</a></h4><ul><li>操作系統 – CentOS 6.5 (Final)</li><li>iSCSI 目標器 IP – 192.168.0.50</li><li>使用的端口 : TCP 3260</li></ul><p><strong>警告</strong>：永遠不要在LUN還掛載在客户端（發起程序）時停止服務。</p><h3 id="客户端設置" tabindex="-1">客户端設置 <a class="header-anchor" href="#客户端設置" aria-label="Permalink to “客户端設置”">​</a></h3><p><strong>1.</strong> 在客户端，我們需要安裝包‘<strong>iSCSI-initiator-utils</strong>’，用下面的命令搜索包。</p><pre><code># yum search iscsi
</code></pre><p><strong>示例輸出</strong></p><pre><code>============================= N/S Matched: iscsi ================================
iscsi-initiator-utils.x86_64 : iSCSI daemon and utility programs
iscsi-initiator-utils-devel.x86_64 : Development files for iscsi-initiator-utils
</code></pre><p><strong>2.</strong> 找到了包，就用下面的yum命令安裝初始化包。</p><pre><code># yum install iscsi-initiator-utils.x86_64
</code></pre><p><strong>3.</strong> 安裝完畢後，我們需要發現<strong>目標器</strong>上的共享。客户端的命令有點難記，因此我們使用man找到需要運行的命令列表。</p><pre><code># man iscsiadm
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/man-iscsiadm.jpg" alt="man iscsiadm"></p><p><em>man iscsiadm</em></p><p><strong>4.</strong> 按下<strong>SHIFT+G</strong> 進入man頁的底部並且稍微向上滾動找到示例的登錄命令。下面的發現命令中，需要用我們的<strong>服務器IP地址</strong>來替換。</p><pre><code># iscsiadm --mode discoverydb --type sendtargets --portal 192.168.0.200 --discover
</code></pre><p><strong>5.</strong> 這裏我們從下面的命令輸出中找到了iSCSI的限定名（iqn）。</p><pre><code>192.168.0.200:3260,1 iqn.2014-07.com.tecmint:tgt1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Discover-Target.jpg" alt="Discover Target"></p><p><em>發現服務器</em></p><p><strong>6.</strong> 要登錄就用下面的命令來連接一台LUN到我們本地系統中，這會與服務器驗證並允許我們登錄LUN。</p><pre><code># iscsiadm --mode node --targetname iqn.2014-07.com.tecmint:tgt1 --portal 192.168.0.200:3260 --login
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Login-To-Target-Server.jpg" alt="Login To Target Server"></p><p><em>登錄到服務器</em></p><p><strong>注意</strong>：登出使用登錄命令並在命令的最後使用logout來替換。</p><pre><code># iscsiadm --mode node --targetname iqn.2014-07.com.tecmint:tgt1 --portal 192.168.0.200:3260 --logout
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Logout-from-Target-Server.jpg" alt="Logout from Target Server"></p><p><em>登出服務器</em></p><p><strong>7.</strong> 登錄服務器後，使用下面的命令列出節點的記錄行。</p><pre><code># iscsiadm --mode node
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/List-Node.jpg" alt="List Node"></p><p><em>列出節點</em></p><p><strong>8.</strong> 顯示特定節點的所有數據</p><pre><code># iscsiadm --mode node --targetname iqn.2014-07.com.tecmint:tgt1 --portal 192.168.0.200:3260
</code></pre><p><strong>示例輸出</strong></p><pre><code># BEGIN RECORD 6.2.0-873.10.el6
node.name = iqn.2014-07.com.tecmint:tgt1
node.tpgt = 1
node.startup = automatic
node.leading_login = No
iface.hwaddress = &lt;empty&gt;
iface.ipaddress = &lt;empty&gt;
iface.iscsi_ifacename = default
iface.net_ifacename = &lt;empty&gt;
iface.transport_name = tcp
iface.initiatorname = &lt;empty&gt;
iface.bootproto = &lt;empty&gt;
iface.subnet_mask = &lt;empty&gt;
iface.gateway = &lt;empty&gt;
iface.ipv6_autocfg = &lt;empty&gt;
iface.linklocal_autocfg = &lt;empty&gt;
....
</code></pre><p><strong>9.</strong> 接着列出使用的磁盤，fdisk會列出所有的登錄認證過的磁盤。</p><pre><code># fdisk -l /dev/sda
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/List-Disks.jpg" alt="List Disks"></p><p>列出磁盤</p><p><strong>10.</strong> 運行fdisk命令來創建一個新的分區</p><pre><code># fdisk -cu /dev/sda
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Create-New-Partition.jpg" alt="Create New Partition"></p><p><em>創建新分區</em></p><p><strong>注意</strong>：在使用fdisk創建新分區之後，我們無需重啓，就像使用我們本地的文件系統一樣就行。因為這個將遠程共享存儲掛載到本地了。</p><p><strong>11.</strong> 格式化新創建的分區</p><pre><code># mkfs.ext4 /dev/sda1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Format-New-Partition.jpg" alt="Format New Partition"></p><p><em>格式化新分區</em></p><p><strong>12.</strong> 創建一個目錄來掛載新創建的分區</p><pre><code># mkdir /mnt/iscsi_share
# mount /dev/sda1 /mnt/iscsi_share/
# ls -l /mnt/iscsi_share/
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Mount-New-Partition.jpg" alt="Mount New Partition"></p><p><em>掛載新分區</em></p><p><strong>13.</strong> 列出掛載點</p><pre><code># df -Th
</code></pre><ul><li><strong>-T</strong> – 輸出文件系統類型</li><li><strong>-h</strong> – 以易讀的方式顯示大小</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/List-New-Partition.jpg" alt="List New Partition"></p><p><em>列出新分區</em></p><p><strong>14.</strong> 如果需要永久掛載，使用fdtab文件</p><pre><code># vim /etc/fstab
</code></pre><p><strong>15.</strong>在fstab後追加下面行</p><pre><code>/dev/sda1  /mnt/iscsi_share/   ext4    defaults,_netdev   0 0
</code></pre><p><strong>注意：</strong> 在fdtab中使用_netdev，説明這是一個網絡設備。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Auto-Mount-Partition.jpg" alt="Auto Mount Partition"></p><p><em>自動掛載分區</em></p><p><strong>16.</strong> 最後檢查我們fstab文件是否有錯誤。</p><pre><code># mount -av
</code></pre><ul><li><strong>-a</strong> – 所有掛載點</li><li><strong>-v</strong> – 冗餘模式</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Verify-fstab-Entries.jpg" alt="Verify fstab Entries"></p><p><em>驗證fstab文件</em></p><p>我們已經成功完成了我們的客户端配置。現在讓我們像本地磁盤一樣使用它吧。</p><hr>`,72)),r("p",null,[t[3]||(t[3]=e("via: ",-1)),o(n,{href:"http://www.tecmint.com/iscsi-initiator-client-setup/"},{default:i(()=>[...t[2]||(t[2]=[e("http://www.tecmint.com/iscsi-initiator-client-setup/",-1)])]),_:1})]),r("p",null,[t[7]||(t[7]=e("作者：",-1)),o(n,{href:"http://www.tecmint.com/author/babinlonston/"},{default:i(()=>[...t[4]||(t[4]=[e("Babin Lonston",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),o(n,{href:"https://github.com/geekpi"},{default:i(()=>[...t[5]||(t[5]=[e("geekpi",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[6]||(t[6]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[12]||(t[12]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:i(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const h=s(d,[["render",g]]);export{I as __pageData,h as default};
